/bin/zsh -lc "env GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null /opt/homebrew/bin/python3 -c 'import sys,json,pathlib,time; sys.path.insert(0,\"research\"); from balanced_f80 import *; from scan import generate; t=time.monotonic(); fs=[]; count=0
for path,(a,b,p) in generate(40):
 lo,hi=A,B
 for c in path:
  m=mm(lo,hi)
  if c==\"L\":hi=m
  else:lo=m
 m=mm(lo,hi); count+=1
 for k,q in enumerate(m):
  f=failure(q)
  if f:fs.append(dict(a=a,b=b,path=path,entry=k,**f))
res=dict(bound=40,count=count,failures=fs,seconds=time.monotonic()-t); pathlib.Path(\"evidence/markov-f80fb8bc/source-all-entry-40.json\").write_text(json.dumps(res,indent=2)); print(res)'"

