/bin/zsh -lc "env GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null /opt/homebrew/bin/python3 -c 'import sys,json,pathlib; sys.path.insert(0,\"evidence/markov\"); from scan import generate
fs={}; count=0
for path,(a,b,p) in generate(25):
 d=a+b-1
 for i,j in p:
  for key,pts in [(\"uv\",[(i,j),(i+1,j+1),(i+1,j),(i,j+1)]),(\"uw\",[(i,j),(i,j-1),(i+1,j-1),(i-1,j)]),(\"vw\",[(i,j),(i-1,j),(i-1,j+1),(i,j-1)])]:
   x,y,z,w=[p.get(pt,0) for pt in pts];count+=1
   if x*y>z*w and key not in fs:fs[key]=dict(a=a,b=b,path=path,start=[i,j],pts=pts,values=[x,y,z,w])
res=dict(status=\"finite rhombus tests; orientation logged explicitly\",count=count,failures=fs);pathlib.Path(\"evidence/markov-f80fb8bc/rhombus-25.json\").write_text(json.dumps(res,indent=2)); print(res)'"

