/bin/zsh -lc "env GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null /opt/homebrew/bin/python3 -c 'import sys,json,pathlib; sys.path.insert(0,\"research\"); from balanced_f80 import *; from math import gcd
stack=[(\"\",I)]; found=[]
for n in range(1,15):
 ns=[]
 for w,m in stack:
  for c,g in [(\"A\",A),(\"B\",B)]:
   z=w+c
   if not balanced(z):continue
   M=mm(m,g);ns.append((z,M))
   if z.startswith(\"A\") and z.endswith(\"B\") and gcd(z.count(\"B\"),len(z))==1:
    f=failure(M[1])
    if f:found.append(dict(word=z,**f))
 stack=ns
 if found:break
pathlib.Path(\"evidence/markov-f80fb8bc/balanced-reduced-obstruction.json\").write_text(json.dumps(found,indent=2)); print(found[:3])'"

